namespace SonosFlow.App.Sound;

/// <summary>
/// "Audiora Enchanted": original sounds generated by synthesis (no recordings, no borrowed melodies).
/// One timbre palette — a soft marimba voice and a glass bell with a very short tail — and one small motif
/// (D major pentatonic: A–D–F♯–A) that returns in every sound, so Audiora is recognisable without looking.
/// Deterministic: the same sound renders to the same samples every time.
/// </summary>
/// <summary>The lead voice of the set. Marimba is the one in use; the others are alternatives kept for auditioning.</summary>
public enum Timbre { Ocarina, Crystal, Harp, Kalimba, Marimba }

public static class EnchantedSynth
{
    [ThreadStatic] private static Timbre _timbre;
    public const int SampleRate = 48000;
    /// <summary>Peak ceiling (≈ −4.4 dBFS) and loudness target (≈ −18 dBFS RMS) before the user's volume.</summary>
    public const float PeakCeiling = 0.6f, TargetRms = 0.125f;

    private const double TwoPi = Math.PI * 2;

    // Semitones from A4 (440 Hz) for the pentatonic palette.
    private const int D4 = -7, A4 = 0, Bb4 = 1, B4 = 2, D5 = 5, Fs5 = 9, A5 = 12, D6 = 17, E6 = 19, Fs6 = 21, A6 = 24;

    private static double Hz(int semitonesFromA4) => 440.0 * Math.Pow(2, semitonesFromA4 / 12.0);

    /// <summary>Mono float samples at 48 kHz, peak ≤ <see cref="PeakCeiling"/>, silent at both ends.</summary>
    public static float[] Render(SoundId id) => Render(id, DefaultTimbre);

    /// <summary>The voice chosen for Audiora: warm, round and relaxing (a soft marimba) with glass-bell accents.</summary>
    public const Timbre DefaultTimbre = Timbre.Marimba;

    public static float[] Render(SoundId id, Timbre timbre)
    {
        var previous = _timbre;
        _timbre = timbre;
        try { return RenderCore(id); }
        finally { _timbre = previous; }
    }

    private static float[] RenderCore(SoundId id)
    {
        switch (id)
        {
            case SoundId.Connected: // an ascending arpeggio with a bright bell crown: success, discovery
            {
                var b = Buf(1.0);
                Ocarina(b, 0.00, Hz(A4), 0.13, 0.80); Ocarina(b, 0.11, Hz(D5), 0.13, 0.80);
                Ocarina(b, 0.22, Hz(Fs5), 0.14, 0.85); Ocarina(b, 0.33, Hz(A5), 0.30, 0.95);
                Bell(b, 0.11, Hz(D6), 0.20, 0.16); Bell(b, 0.22, Hz(Fs6), 0.22, 0.16);
                Bell(b, 0.33, Hz(A6), 0.34, 0.22); Bell(b, 0.42, Hz(D6), 0.30, 0.12);
                return Finish(b, 7000, 0.30, 0.15, 0.90, SoundCatalog.Info(id).Level);
            }
            case SoundId.ConnectionLost: // two soft descending notes with a darker resonance: noticed, never alarming
            {
                var b = Buf(0.9);
                Ocarina(b, 0.00, Hz(Fs5), 0.20, 0.80); Ocarina(b, 0.20, Hz(D5), 0.30, 0.75);
                Bell(b, 0.20, Hz(D5), 0.32, 0.12);
                return Finish(b, 3200, 0.38, 0.25, 0.80, SoundCatalog.Info(id).Level);
            }
            case SoundId.Reconnected: // a short bright pair: the connection is back
            {
                var b = Buf(0.6);
                Ocarina(b, 0.00, Hz(A5), 0.10, 0.70); Ocarina(b, 0.09, Hz(D6), 0.22, 0.80);
                Bell(b, 0.09, Hz(D6), 0.25, 0.20);
                return Finish(b, 7000, 0.25, 0.12, 0.50, SoundCatalog.Info(id).Level);
            }
            case SoundId.Error: // a gentle semitone "hmm" with a low note: unmistakable, not a beep
            {
                var b = Buf(0.6);
                Bell(b, 0.00, Hz(B4), 0.22, 0.50); Bell(b, 0.06, Hz(Bb4), 0.22, 0.45);
                Ocarina(b, 0.10, Hz(D4), 0.20, 0.60);
                return Finish(b, 3800, 0.20, 0.10, 0.50, SoundCatalog.Info(id).Level);
            }
            case SoundId.StreamStart: // open fifths rising: setting out
            {
                var b = Buf(0.9);
                Ocarina(b, 0.00, Hz(D5), 0.14, 0.80); Ocarina(b, 0.13, Hz(A5), 0.14, 0.85); Ocarina(b, 0.26, Hz(D6), 0.30, 0.90);
                Bell(b, 0.26, Hz(D6), 0.30, 0.15);
                return Finish(b, 6500, 0.30, 0.20, 0.80, SoundCatalog.Info(id).Level);
            }
            case SoundId.StreamStop: // the same fifths, falling, with a longer tail: coming home
            {
                var b = Buf(0.95);
                Ocarina(b, 0.00, Hz(D6), 0.12, 0.70); Ocarina(b, 0.13, Hz(A5), 0.12, 0.70); Ocarina(b, 0.26, Hz(D5), 0.32, 0.80);
                Bell(b, 0.26, Hz(D5), 0.35, 0.12);
                return Finish(b, 5000, 0.34, 0.25, 0.85, SoundCatalog.Info(id).Level);
            }
            case SoundId.ConfigChanged: // one clear glass note
            {
                var b = Buf(0.3);
                Bell(b, 0.000, Hz(A5), 0.06, 0.80); Bell(b, 0.015, Hz(D6), 0.05, 0.30);
                return Finish(b, 8000, 0.12, 0.05, 0.17, SoundCatalog.Info(id).Level);
            }
            case SoundId.ToggleOn: // D→A, up
            {
                var b = Buf(0.3);
                Bell(b, 0.00, Hz(D5), 0.05, 0.70); Bell(b, 0.05, Hz(A5), 0.07, 0.80);
                return Finish(b, 8000, 0.10, 0.04, 0.16, SoundCatalog.Info(id).Level);
            }
            case SoundId.ToggleOff: // A→D, down, a little darker
            {
                var b = Buf(0.3);
                Bell(b, 0.00, Hz(A5), 0.05, 0.60); Bell(b, 0.05, Hz(D5), 0.08, 0.60);
                return Finish(b, 5000, 0.10, 0.04, 0.16, SoundCatalog.Info(id).Level);
            }
            case SoundId.Navigate: // a barely-there tick
            {
                var b = Buf(0.15);
                Bell(b, 0.00, Hz(E6), 0.018, 1.0);
                return Finish(b, 9000, 0.0, 0.0, 0.07, SoundCatalog.Info(id).Level);
            }
            default: throw new ArgumentOutOfRangeException(nameof(id));
        }
    }

    // ── voices ────────────────────────────────────────────────────────────────

    private static float[] Buf(double seconds) => new float[(int)(seconds * SampleRate)];

    /// <summary>The lead voice of every motif, in the timbre being rendered.</summary>
    private static void Ocarina(float[] b, double start, double hz, double length, double gain)
    {
        switch (_timbre)
        {
            case Timbre.Crystal: Bell(b, start, hz, Math.Max(0.22, length * 1.6), gain * 0.9); break;
            case Timbre.Harp: Pluck(b, start, hz, length, gain); break;
            case Timbre.Kalimba: Tine(b, start, hz, length, gain, [1, 5.4, 9.8], [1, 0.22, 0.08], 0.30); break;
            case Timbre.Marimba: Tine(b, start, hz * 0.5, length, gain * 1.1, [1, 4.0, 9.2], [1, 0.45, 0.12], 0.38); break;
            default: OcarinaVoice(b, start, hz, length, gain); break;
        }
    }

    /// <summary>Plucked string (harp / soft lute): harmonics dying faster the higher they are, a tiny pluck noise.</summary>
    private static void Pluck(float[] b, double start, double hz, double length, double gain)
    {
        int i0 = (int)(start * SampleRate), n = (int)((length * 2.2 + 0.35) * SampleRate);
        double tau = 0.18 + length * 1.2, noise = 0;
        uint seed = 123456789u ^ (uint)(hz * 1000);
        for (int k = 0; k < n && i0 + k < b.Length; k++)
        {
            double t = k / (double)SampleRate, s = 0;
            for (int h = 1; h <= 6; h++)
            {
                double f = hz * h;
                if (f > 12000) break;
                s += Math.Sin(TwoPi * f * t) * Math.Exp(-t / (tau / (1 + 0.6 * (h - 1)))) / Math.Pow(h, 1.3);
            }
            seed ^= seed << 13; seed ^= seed >> 17; seed ^= seed << 5;
            noise += 0.3 * ((seed / (double)uint.MaxValue * 2 - 1) - noise);
            s += 0.08 * noise * Math.Exp(-t / 0.006);
            b[i0 + k] += (float)(gain * Smooth(Math.Min(1, t / 0.004)) * s * 0.5);
        }
    }

    /// <summary>Struck tine or bar (kalimba, marimba): few partials, quick round attack, short natural decay.</summary>
    private static void Tine(float[] b, double start, double hz, double length, double gain, double[] ratios, double[] amps, double decay)
    {
        int i0 = (int)(start * SampleRate), n = (int)(decay * 5 * SampleRate);
        double scale = 0.5 + length * 2;
        for (int k = 0; k < n && i0 + k < b.Length; k++)
        {
            double t = k / (double)SampleRate, s = 0;
            for (int p = 0; p < ratios.Length; p++)
            {
                double f = hz * ratios[p];
                if (f > 12000) break;
                s += amps[p] * Math.Sin(TwoPi * f * t) * Math.Exp(-t / (decay * scale / (1 + 1.2 * p)));
            }
            b[i0 + k] += (float)(gain * Smooth(Math.Min(1, t / 0.002)) * s * 0.5);
        }
    }

    /// <summary>Soft wooden-flute voice: sine + gentle 2nd/3rd harmonics, late vibrato, a breath of noise in the attack.</summary>
    private static void OcarinaVoice(float[] b, double start, double hz, double length, double gain)
    {
        const double attack = 0.022, decayTo = 0.78, decayTime = 0.07, release = 0.12;
        int i0 = (int)(start * SampleRate), n = (int)((length + release) * SampleRate);
        double phase = 0, noise = 0;
        uint seed = 2463534242u ^ (uint)(hz * 1000);
        for (int k = 0; k < n && i0 + k < b.Length; k++)
        {
            double t = k / (double)SampleRate;
            double sustain = t < decayTime ? 1 - (1 - decayTo) * (t / decayTime) : decayTo;
            double env = t < length ? sustain : sustain * Cos01(Math.Min(1, (t - length) / release));
            env *= Smooth(Math.Min(1, t / attack));
            double vibrato = 1 + 0.0035 * Math.Sin(TwoPi * 5.3 * t) * Math.Min(1, t / 0.15);
            phase += TwoPi * hz * vibrato / SampleRate;
            seed ^= seed << 13; seed ^= seed >> 17; seed ^= seed << 5;
            noise += 0.35 * ((seed / (double)uint.MaxValue * 2 - 1) - noise); // low-passed breath
            double breath = 0.05 * noise * Math.Exp(-t / 0.05);
            double s = Math.Sin(phase) + 0.20 * Math.Sin(2 * phase) + 0.07 * Math.Sin(3 * phase) + breath;
            b[i0 + k] += (float)(gain * env * s * 0.5);
        }
    }

    /// <summary>Glass bell: inharmonic partials, the upper ones dying faster.</summary>
    private static void Bell(float[] b, double start, double hz, double decay, double gain)
    {
        if (_timbre is Timbre.Harp or Timbre.Kalimba or Timbre.Marimba) gain *= 0.4; // accents, not a second lead
        double[] ratios = [1, 2.756, 5.404, 8.933], amps = [1, 0.32, 0.14, 0.06];
        int i0 = (int)(start * SampleRate), n = (int)(decay * 5 * SampleRate);
        for (int k = 0; k < n && i0 + k < b.Length; k++)
        {
            double t = k / (double)SampleRate;
            double sum = 0;
            for (int p = 0; p < ratios.Length; p++)
            {
                double f = hz * ratios[p];
                if (f > 12000) break;
                sum += amps[p] * Math.Sin(TwoPi * f * t) * Math.Exp(-t / (decay / (1 + 0.9 * p)));
            }
            b[i0 + k] += (float)(gain * Smooth(Math.Min(1, t / 0.003)) * sum * 0.5);
        }
    }

    // ── finishing ─────────────────────────────────────────────────────────────

    /// <summary>Reverb tail, tone, trim, edge fades (no clicks) and loudness matching.</summary>
    private static float[] Finish(float[] raw, double lowPassHz, double wet, double tailSeconds, double maxSeconds, double level)
    {
        var x = wet > 0 ? Reverb(raw, wet, tailSeconds) : (float[])raw.Clone();

        double a = 1 - Math.Exp(-TwoPi * lowPassHz / SampleRate), lp = 0;
        for (int i = 0; i < x.Length; i++) { lp += a * (x[i] - lp); x[i] = (float)lp; }

        int len = Math.Min(x.Length, (int)(maxSeconds * SampleRate));
        var y = new float[len];
        Array.Copy(x, y, len);

        int fadeIn = (int)(0.002 * SampleRate), fadeOut = Math.Min(len / 3, (int)(0.025 * SampleRate));
        for (int i = 0; i < fadeIn && i < len; i++) y[i] *= (float)Smooth(i / (double)fadeIn);
        for (int i = 0; i < fadeOut; i++) y[len - 1 - i] *= (float)Smooth(i / (double)fadeOut);

        double peak = 0, energy = 0; int active = 0;
        foreach (var s in y)
        {
            peak = Math.Max(peak, Math.Abs(s));
            if (Math.Abs(s) > 0.003) { energy += (double)s * s; active++; }
        }
        if (peak <= 0 || active == 0) return y;
        double rms = Math.Sqrt(energy / active);
        double gain = Math.Min(PeakCeiling / peak, TargetRms / rms) * level;
        // The level factor may only lower a sound: the ceiling must hold even for the loudest.
        gain = Math.Min(gain, PeakCeiling / peak);
        for (int i = 0; i < y.Length; i++) y[i] = (float)(y[i] * gain);
        return y;
    }

    /// <summary>Schroeder reverb: four damped combs and two all-passes. Short, warm, never washy.</summary>
    private static float[] Reverb(float[] dry, double wet, double tailSeconds)
    {
        int len = dry.Length + (int)(tailSeconds * SampleRate);
        var input = new float[len];
        Array.Copy(dry, input, dry.Length);
        var acc = new float[len];
        foreach (double ms in new[] { 29.7, 37.1, 41.1, 43.7 })
        {
            int d = (int)(ms * SampleRate / 1000);
            var comb = new float[len];
            float damp = 0;
            for (int n = 0; n < len; n++)
            {
                float fed = n >= d ? comb[n - d] : 0;
                damp = fed * 0.65f + damp * 0.35f;
                comb[n] = input[n] + 0.70f * damp;
                acc[n] += comb[n] * 0.25f;
            }
        }
        foreach (double ms in new[] { 5.0, 1.7 })
        {
            int d = (int)(ms * SampleRate / 1000);
            var ap = new float[len];
            for (int n = 0; n < len; n++)
            {
                float xd = n >= d ? acc[n - d] : 0, yd = n >= d ? ap[n - d] : 0;
                ap[n] = -0.5f * acc[n] + xd + 0.5f * yd;
            }
            acc = ap;
        }
        var outp = new float[len];
        for (int n = 0; n < len; n++) outp[n] = (n < dry.Length ? dry[n] : 0) + (float)wet * acc[n];
        return outp;
    }

    /// <summary>0→1 with zero slope at both ends (cosine S-curve).</summary>
    private static double Smooth(double t) => 0.5 - 0.5 * Math.Cos(Math.PI * Math.Clamp(t, 0, 1));
    /// <summary>1→0 cosine release.</summary>
    private static double Cos01(double t) => 0.5 + 0.5 * Math.Cos(Math.PI * Math.Clamp(t, 0, 1));
}
